const fs = require('node:fs');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
(async () => {
 const { requirePhase008FailureChain } = await import('./docs/phase-plans/phase008-evidence.mjs');
 const digest = (bytes) => crypto.createHash('sha256').update(bytes).digest('hex');
 const readJson = (file) => JSON.parse(fs.readFileSync(file));
 const hashFile = (file) => digest(fs.readFileSync(file));
 const original = readJson('docs/phase-plans/Phase008.json');
 assert.equal(original.attemptId,'attempt-5');
 requirePhase008FailureChain(original,{readJson,hashFile});
 const cases=[];
 for(const [name,change] of [
  ['drop-all-previous-attempts',value=>{value.previousAttempts=[];}],
  ['omit-an-earlier-attempt',value=>{value.previousAttempts.splice(1,1);}],
  ['reverse-previous-attempt-order',value=>{value.previousAttempts.reverse();}]
 ]) {
  const value=structuredClone(original);
  change(value);
  requirePhase008FailureChain(value,{readJson,hashFile});
  cases.push({name,actual:'ACCEPT',required:'REJECT',providedAttempts:value.previousAttempts.map(entry=>entry.attemptId)});
 }
 const rebound=structuredClone(original);
 const previous=rebound.previousAttempts[0];
 const changed=readJson(previous.failurePath);
 changed.reason='Synthetic replacement diagnostic for an already hash-bound historical failure';
 const changedBytes=Buffer.from(JSON.stringify(changed)+'\n');
 const newHash=digest(changedBytes);
 assert.notEqual(previous.failureHash,newHash);
 const oldFailureHash=previous.failureHash;
 previous.failureHash=newHash;
 requirePhase008FailureChain(rebound,{
  readJson:file=>file===previous.failurePath?JSON.parse(changedBytes):readJson(file),
  hashFile:file=>file===previous.failurePath?newHash:hashFile(file),
 });
 cases.push({name:'alter-old-failure-and-rebind-only-current-plan-hash',actual:'ACCEPT',required:'REJECT',failurePath:previous.failurePath,oldFailureHash,newFailureHash:newHash,olderFrozenPlanMappingsChanged:false});
 console.log(JSON.stringify({scope:'READ_ONLY_REAL_PHASE008_FAILURE_CHAIN_FUNCTION',attemptId:original.attemptId,baselineAccepted:true,originalPreviousCount:original.previousAttempts.length,filesModified:false,databaseAccessed:false,cases}));
})().catch(error=>{console.error(error);process.exitCode=1;});
